code.css:
*{box-sizing:border-box}
body{margin:0;background:#f4f6f8;color:#1e2226;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;font-size:16px;line-height:1.7}
a{color:#1b4fa0;text-decoration:none}
a:hover{text-decoration:underline}
a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #1b4fa0;outline-offset:2px}
h1,h2,h3{font-weight:600;color:#1e2226}
h1{font-size:32px;line-height:1.35;margin:0;letter-spacing:-0.01em}
h2{font-size:22px;line-height:1.4;margin:0 0 10px}
h3{font-size:17px;margin:0 0 14px}
p{margin:0 0 14px}
ul,ol{margin:0;padding:0}
.wrap{max-width:1120px;margin:0 auto;padding:0 24px}
[data-system-icon]{display:inline-block;width:1em;height:1em;vertical-align:-0.12em}
.site-header{background:#fff;border-bottom:1px solid #d7dde2}
.site-header .wrap{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px 24px;min-height:64px;padding-top:8px;padding-bottom:8px}
.brand{display:flex;align-items:center;gap:10px;font-size:17px;font-weight:600;color:#1e2226;letter-spacing:.01em}
.brand:hover{text-decoration:none}
.brand-mark{display:inline-block;width:10px;height:10px;background:#1b4fa0}
.site-nav ul{display:flex;flex-wrap:wrap;gap:4px 22px;list-style:none}
.site-nav a{display:inline-block;padding:6px 0;font-size:15px;color:#3a444c;border-bottom:1px solid transparent}
.site-nav a:hover{color:#1b4fa0;text-decoration:none;border-bottom-color:#1b4fa0}
.btn{display:inline-flex;align-items:center;gap:8px;background:#1b4fa0;color:#fff;border:1px solid #1b4fa0;border-radius:2px;padding:11px 22px;font-size:15px;font-weight:600;line-height:1.4}
.btn:hover{background:#123a78;border-color:#123a78;color:#fff;text-decoration:none}
.btn-on-dark{background:#fff;color:#123a78;border-color:#fff}
.btn-on-dark:hover{background:#dbe5f5;border-color:#dbe5f5;color:#123a78}
.link-plain{font-size:15px;color:#1b4fa0}
.hero{background:#fff;padding:52px 0 48px}
.hero-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,0.9fr);gap:44px;align-items:start}
.eyebrow{margin:0 0 16px;font-size:13px;letter-spacing:.1em;color:#4a545c}
.lede{font-size:17px;color:#33383d;max-width:34em;margin:0 0 18px}
.hero-note{font-size:15px;color:#4a545c;max-width:32em;margin:0 0 26px}
.hero-actions{margin:0 0 14px}
.hero-link{margin:0}
.hero-side{border-top:2px solid #1e2226;padding-top:16px}
.side-title{margin:0 0 10px;font-size:14px;letter-spacing:.08em;color:#4a545c}
.page-head{background:#fff;padding:48px 0 36px}
.page-head h1{margin-bottom:14px}
.page-head .lede{margin:0}
.section{border-top:1px solid #d7dde2;padding:44px 0}
.section-head{margin-bottom:24px}
.section-head p{margin:0;color:#4a545c;max-width:38em}
.two-col{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:44px;align-items:start}
.spec{margin:0}
.spec-row{display:grid;grid-template-columns:96px minmax(0,1fr);gap:14px;padding:11px 0;border-bottom:1px solid #d7dde2;font-variant-numeric:tabular-nums}
.spec-row dt{font-size:15px;color:#4a545c}
.spec-row dd{margin:0;font-size:15px}
.spec-row-key dd{font-weight:600}
.spec-col h3{margin:0;padding-bottom:10px;border-bottom:1px solid #b6c0c8}
.table{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}
.table th,.table td{text-align:left;vertical-align:top;padding:12px 18px 12px 0;border-bottom:1px solid #d7dde2}
.table th:last-child,.table td:last-child{padding-right:0}
.table thead th{border-bottom:1px solid #b6c0c8;color:#4a545c;font-weight:600}
.table tbody th{font-weight:600}
.table-plain tbody th{width:42%;font-weight:400;color:#4a545c}
.table-plain tbody td{font-weight:600}
.line-list{list-style:none;border-top:1px solid #b6c0c8;margin:0}
.line-list li{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 16px;padding:12px 0;border-bottom:1px solid #d7dde2;font-size:15px;font-variant-numeric:tabular-nums}
.line-list .k{font-weight:600}
.line-list .v{color:#4a545c}
.note{font-size:14px;color:#4a545c;max-width:38em}
.after-note{margin:20px 0 0}
.bounds{background:#fff;border-left:3px solid #1b4fa0;padding:26px 30px}
.bounds h2{margin-bottom:14px}
.bounds-list{margin:0;padding-left:20px}
.bounds-list li{margin-bottom:8px;max-width:38em}
.bounds-list li:last-child{margin-bottom:0}
.section-end{display:flex;flex-wrap:wrap;align-items:center;gap:12px 20px;margin-top:28px}
.section-end p{margin:0}
.section-end-text{color:#4a545c;font-size:15px}
.fig-row{display:flex;flex-wrap:wrap;gap:28px;margin-top:28px}
.fig{margin:0}
.fig figcaption{margin-top:10px;font-size:13px;color:#4a545c}
.fig-col{display:flex;flex-direction:column;gap:6px}
.draw{position:relative;width:76px;height:56px}
.d-body,.d-flap,.d-outer,.d-inner,.d-shell,.d-slot{position:absolute;display:block;border:1.5px solid #4a545c}
.draw-tuck .d-body{left:0;bottom:0;width:76px;height:38px}
.draw-tuck .d-flap{left:13px;top:0;width:50px;height:16px;border-bottom:0}
.draw-drawer .d-outer{left:0;top:0;width:54px;height:56px}
.draw-drawer .d-inner{left:26px;top:16px;width:50px;height:26px}
.draw-tray .d-shell{left:0;top:0;width:76px;height:56px}
.draw-tray .d-slot{width:14px;height:14px;border-radius:50%}
.draw-tray .d-slot-1{left:10px;top:20px}
.draw-tray .d-slot-2{left:31px;top:20px}
.draw-tray .d-slot-3{left:52px;top:20px}
.steps{list-style:none;border-top:1px solid #b6c0c8;max-width:44em}
.steps li{display:grid;grid-template-columns:32px minmax(0,1fr);gap:16px;padding:14px 0;border-bottom:1px solid #d7dde2}
.step-num{font-size:14px;font-weight:600;color:#1b4fa0;font-variant-numeric:tabular-nums}
.step-k{margin:0;font-weight:600}
.faq{border-top:1px solid #b6c0c8}
.faq-item{padding:16px 0;border-bottom:1px solid #d7dde2;max-width:38em}
.faq-item .q{margin:0 0 6px;font-weight:600}
.faq-item .a{margin:0;color:#33383d}
.cta-band{background:#123a78;padding:40px 0}
.cta-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:18px}
.cta-line{margin:0;font-size:19px;font-weight:600;color:#fff;max-width:30em}
.cta-action{margin:0}
.contact-grid{display:grid;grid-template-columns:minmax(0,0.85fr) minmax(0,1.15fr);gap:44px;align-items:start}
.mail-line{font-size:16px;color:#1e2226;font-variant-numeric:tabular-nums}
.site-footer{background:#eef1f3;border-top:1px solid #d7dde2}
.footer-grid{display:grid;grid-template-columns:1.2fr 1fr 1.3fr;gap:28px;padding-top:36px;padding-bottom:36px}
.footer-brand{margin:0 0 8px;font-size:16px;font-weight:600;color:#33383d}
.footer-line{margin:0;font-size:14px;color:#4a545c;max-width:26em}
.footer-nav ul{display:flex;flex-wrap:wrap;gap:8px 20px;list-style:none}
.footer-nav a{font-size:15px;color:#1b4fa0}
.footer-key{margin:0 0 6px;font-size:13px;letter-spacing:.08em;color:#4a545c}
.footer-value{margin:0 0 6px;font-size:15px;color:#33383d;font-variant-numeric:tabular-nums}
@media (max-width:900px){
.hero-grid{grid-template-columns:minmax(0,1fr);gap:32px}
.two-col{grid-template-columns:minmax(0,1fr);gap:32px}
.contact-grid{grid-template-columns:minmax(0,1fr);gap:30px}
.footer-grid{grid-template-columns:minmax(0,1fr);gap:22px}
}
@media (max-width:768px){
.wrap{padding:0 18px}
h1{font-size:26px}
h2{font-size:20px}
.hero{padding:36px 0 32px}
.page-head{padding:36px 0 28px}
.section{padding:34px 0}
.spec-row{grid-template-columns:84px minmax(0,1fr);gap:10px}
.bounds{padding:22px 20px}
}
@media (max-width:480px){
.site-nav ul{gap:4px 16px}
h1{font-size:24px}
.spec-row{grid-template-columns:76px minmax(0,1fr);gap:8px}
.table th,.table td{padding:10px 12px 10px 0}
.fig-row{gap:22px}
}

:root{--paper:#f5f2ea;--paper-2:#eae5d8;--paper-3:#fbf9f3;--ink:#23211d;--ink-2:#55524a;--line:#d5cebd;--line-dark:#4b463d;--accent:#a83b1c;--accent-dark:#8c3116;--dark:#26241f;--dark-ink:#f2efe6;--dark-ink-2:#cfc9bb;--r:2px;--wrap:1120px}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Source Han Sans SC","Noto Sans CJK SC",sans-serif;font-size:17px;line-height:1.75}
h1,h2,h3{margin:0;font-weight:700;line-height:1.35}
p{margin:0}
ul,ol,dl,dd{margin:0;padding:0}
ul,ol{list-style:none}
a{color:inherit;text-decoration:none}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
.section{padding:66px 0}
.section--tight{padding:44px 0}
.section--edge{border-top:1px solid var(--line)}
.section--paper2{background:var(--paper-2)}
.section--dark{background:var(--dark);color:var(--dark-ink)}
.section h2{font-size:clamp(23px,2.5vw,32px)}
.section__lead{margin-top:14px;max-width:44em;color:var(--ink-2);font-size:17.5px}
.section__note{margin-top:20px;max-width:46em;color:var(--ink-2);font-size:15.5px}
.section--dark .section__lead,.section--dark .section__note{color:var(--dark-ink-2)}
.site-header{background:var(--paper);border-bottom:1px solid var(--line)}
.site-header__inner{display:flex;align-items:center;flex-wrap:wrap;gap:28px;min-height:68px;max-width:var(--wrap);margin:0 auto;padding:0 24px}
.brand{font-size:19px;font-weight:700;letter-spacing:.02em;white-space:nowrap}
.nav{display:flex;flex-wrap:wrap;gap:26px;margin-left:auto}
.nav a{font-size:15.5px;color:var(--ink-2);padding:4px 0;border-bottom:2px solid transparent}
.nav a:hover{color:var(--ink);border-bottom-color:var(--accent)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 22px;border:1px solid transparent;border-radius:var(--r);font-size:16px;font-weight:600;line-height:1.3}
.btn--primary{background:var(--accent);color:#fff}
.btn--primary:hover{background:var(--accent-dark)}
.btn--ghost{border-color:var(--ink);color:var(--ink)}
.btn--ghost:hover{background:var(--paper-2)}
.btn--sm{padding:9px 16px;font-size:15px}
.hero{padding:72px 0 64px}
.hero__grid{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(0,1fr);gap:56px;align-items:center}
.hero h1{font-size:clamp(30px,4.2vw,50px);letter-spacing:-.01em;margin-bottom:22px}
.mark{font-style:normal;border-bottom:4px solid var(--accent);padding-bottom:2px}
.hero__lead{font-size:18px;color:var(--ink-2);max-width:30em;margin-bottom:30px}
.hero__actions{display:flex;flex-wrap:wrap;align-items:center;gap:18px}
.schematic{margin:0}
.schematic__frame{border:1px solid var(--ink);background:var(--paper-3);padding:16px;display:flex;min-height:230px}
.schematic__frame--carton .panel{flex:1;border-right:1px dashed var(--ink-2)}
.schematic__frame--carton .panel:last-child{border-right:0}
.schematic__frame--mailer{flex-direction:column;gap:12px;padding:14px}
.schematic__frame--mailer .flap{flex:0 0 24%;border:1px dashed var(--ink-2)}
.schematic__frame--mailer .body{flex:1 1 auto;border:1px solid var(--ink-2)}
.schematic__frame--tray{gap:12px}
.schematic__frame--tray .cavity{flex:1;border:1px solid var(--ink-2);border-radius:48% 48% 34% 34% / 34% 34% 26% 26%;background:var(--paper-2)}
.schematic figcaption{margin-top:12px;font-size:14.5px;color:var(--ink-2)}
.lines{margin:32px 0 0;border-top:1px solid var(--line)}
.lines__row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.85fr) minmax(0,1.5fr);gap:8px 32px;padding:20px 0;border-bottom:1px solid var(--line);align-items:baseline}
.lines__row dt{font-size:18px;font-weight:600}
.lines__row dd{margin:0;font-size:16.5px;font-variant-numeric:tabular-nums}
.section--dark .lines{border-top-color:var(--line-dark)}
.section--dark .lines__row{border-bottom-color:var(--line-dark)}
.section--dark .lines__row dd{color:var(--dark-ink-2)}
.steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 56px;margin-top:30px}
.steps__item{padding:22px 0;border-top:1px solid var(--line)}
.steps__label{font-size:14px;letter-spacing:.06em;color:var(--ink-2);margin-bottom:6px}
.steps__item h3{font-size:18px;margin-bottom:6px}
.steps__item p:last-child{color:var(--ink-2);font-size:16px}
.boundary{border-left:4px solid var(--accent);padding-left:28px;max-width:52em}
.boundary h2{font-size:clamp(22px,2.3vw,28px)}
.boundary p{margin-top:14px;color:var(--ink-2)}
.cta-row{display:flex;align-items:center;justify-content:space-between;gap:28px;flex-wrap:wrap}
.cta-row__text{font-size:19px;max-width:30em}
.page-head{padding:56px 0 40px}
.page-head h1{font-size:clamp(28px,3.4vw,42px)}
.page-head p{margin-top:16px;max-width:40em;color:var(--ink-2)}
.product{margin-top:32px}
.product h3{font-size:21px;margin-bottom:14px}
.product--split{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:48px;align-items:start}
.product--reverse{grid-template-columns:minmax(0,.85fr) minmax(0,1.4fr)}
.spec{display:grid;grid-template-columns:8em minmax(0,1fr)}
.spec dt{padding:12px 0;border-bottom:1px solid var(--line);color:var(--ink-2);font-size:15px}
.spec dd{padding:12px 0;border-bottom:1px solid var(--line);font-size:16.5px;font-variant-numeric:tabular-nums}
.spec-cols{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 48px;margin-top:8px}
.caps{display:flex;flex-wrap:wrap;gap:10px 34px;margin-top:24px;font-size:17.5px}
.equip{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;margin-top:32px;padding-top:24px;border-top:1px solid var(--line)}
.equip dt{font-size:15px;color:var(--ink-2)}
.equip dd{margin-top:4px;font-size:27px;font-weight:700;line-height:1.3;font-variant-numeric:tabular-nums}
.equip dd span{margin-left:5px;font-size:15px;font-weight:400;color:var(--ink-2)}
.flow{margin:30px 0 0}
.flow__item{display:grid;grid-template-columns:56px minmax(0,1fr);gap:24px;padding:22px 0;border-top:1px solid var(--line);align-items:start}
.flow__no{font-size:22px;font-weight:700;line-height:1.5;color:var(--accent);font-variant-numeric:tabular-nums}
.flow__body h3{font-size:18px;margin-bottom:6px}
.flow__body p{color:var(--ink-2);max-width:42em}
.proof{display:grid;grid-template-columns:minmax(0,.55fr) minmax(0,1.45fr);gap:48px;margin-top:32px;align-items:start}
.proof__value{font-size:clamp(42px,6vw,64px);font-weight:700;line-height:1.05;color:var(--accent);font-variant-numeric:tabular-nums}
.proof__value span{margin-left:6px;font-size:17px;font-weight:400;color:var(--ink-2)}
.proof__label{margin-top:10px;font-size:15.5px;color:var(--ink-2)}
.proof__notes p{color:var(--ink-2)}
.leadtime{margin-top:24px}
.leadtime div{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:4px 24px;padding:14px 0;border-top:1px solid var(--line)}
.leadtime dt{font-weight:600}
.leadtime dd{color:var(--ink-2);font-variant-numeric:tabular-nums}
.faq{margin-top:28px;max-width:46em}
.faq dt{padding-top:22px;border-top:1px solid var(--line);font-size:18px;font-weight:700}
.faq dd{padding:8px 0 22px;color:var(--ink-2)}
.contact{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);gap:56px;align-items:start}
.contact__mail{display:flex;align-items:center;gap:10px;margin-top:16px;font-size:19px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.contact__hint{margin-top:18px;max-width:30em;color:var(--ink-2)}
.contact__meta{margin-top:26px;padding-top:18px;border-top:1px solid var(--line);font-size:15.5px;color:var(--ink-2)}
.contact__form{border:1px solid var(--line);background:var(--paper-3);padding:28px;border-radius:var(--r)}
.site-footer{background:var(--dark);color:var(--dark-ink-2);padding:56px 0 44px}
.site-footer__cols{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) minmax(0,.8fr) minmax(0,1fr);gap:40px}
.site-footer__name{font-size:19px;font-weight:700;color:var(--dark-ink);margin-bottom:12px}
.site-footer h2{font-size:14.5px;font-weight:600;color:var(--dark-ink);margin-bottom:12px}
.site-footer p{font-size:15px;line-height:1.8}
.site-footer li{margin-bottom:8px}
.site-footer li a{font-size:15px;color:var(--dark-ink-2);border-bottom:1px solid transparent}
.site-footer li a:hover{color:var(--dark-ink);border-bottom-color:var(--dark-ink-2)}
.site-footer a:focus-visible{outline-color:var(--dark-ink)}
@media (max-width:900px){.hero__grid{grid-template-columns:1fr;gap:40px}.product--split,.product--reverse{grid-template-columns:1fr;gap:32px}.contact{grid-template-columns:1fr;gap:36px}}
@media (max-width:768px){.site-header__inner{flex-direction:column;align-items:flex-start;gap:12px;padding:14px 24px}.nav{margin-left:0;gap:20px}.section{padding:52px 0}.steps{grid-template-columns:1fr;gap:0}.lines__row{grid-template-columns:1fr;gap:4px 0}.equip{grid-template-columns:1fr;gap:16px}.spec-cols{grid-template-columns:1fr;gap:0}.proof{grid-template-columns:1fr;gap:28px}.leadtime div{grid-template-columns:1fr;gap:2px 0}.flow__item{grid-template-columns:44px minmax(0,1fr);gap:16px}.cta-row{flex-direction:column;align-items:flex-start}.site-footer__cols{grid-template-columns:1fr 1fr;gap:32px}}
@media (max-width:520px){.wrap{padding:0 20px}.contact__form{padding:20px}.boundary{padding-left:18px}}
@media (max-width:480px){.spec{grid-template-columns:1fr}.spec dt{padding-bottom:0;border-bottom:0}.spec dd{padding-top:2px}.site-footer__cols{grid-template-columns:1fr}}
